from solution import slugify
import unittest

class SlugifyTests(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(slugify('  Hello, World!  '), 'hello-world')
    def test_runs(self):
        self.assertEqual(slugify('A__B---C'), 'a-b-c')
    def test_empty(self):
        self.assertEqual(slugify('...'), '')

if __name__ == '__main__':
    unittest.main()
